<?php require __DIR__.'/../config/db.php'; $action=$_GET['action']??'list'; if($action==='descriptors'){ $q=$pdo->query("SELECT s.id,s.nama,k.nama kelas,s.descriptor_json FROM siswa s JOIN kelas k ON k.id=s.kelas_id WHERE s.aktif=1 AND s.descriptor_json IS NOT NULL");$rows=[];foreach($q as $r){$r['descriptor']=json_decode($r['descriptor_json'],true);unset($r['descriptor_json']);$rows[]=$r;}out($rows);} if($_SERVER['REQUEST_METHOD']==='POST'){ $b=body();$st=$pdo->prepare('INSERT INTO siswa(nisn,nama,kelas_id,jenis_kelamin,descriptor_json) VALUES(?,?,?,?,?)');$st->execute([$b['nisn'],$b['nama'],$b['kelas_id'],$b['jenis_kelamin']??'L',isset($b['descriptor'])?json_encode($b['descriptor']):null]);out(['ok'=>true,'id'=>$pdo->lastInsertId()]); }$q=$pdo->query('SELECT s.id,s.nisn,s.nama,k.nama kelas,s.jenis_kelamin,s.aktif FROM siswa s JOIN kelas k ON k.id=s.kelas_id ORDER BY s.nama');out($q->fetchAll());
